const CAP=()=>window.Capacitor&&window.Capacitor.isNativePlatform&&window.Capacitor.isNativePlatform()?window.Capacitor:null;
SX.native=!!CAP();
const plug=n=>{const c=CAP();return c&&c.Plugins&&c.Plugins[n]?c.Plugins[n]:null};
if(SX.native)document.documentElement.classList.add('native');
S.hc=S.hc||{};S.steps=S.steps||{};S.sleep=S.sleep||{};S.adh=S.adh||{};
const HC_FIELDS={steps:'Steps',sleep:'Sleep',heartRate:'Heart rate',weight:'Weight',bloodPressure:'Blood pressure',glucose:'Blood sugar',spo2:'SpO₂'};
function hcMerge(m,data){let n=0;const V=(S.vitals[m.id]=S.vitals[m.id]||[]),have=new Set(V.map(v=>v.hc).filter(Boolean));
 (data.steps||[]).forEach(r=>{const d=String(r.date||'').slice(0,10);if(!d||!(r.count>0))return;S.steps[m.id]=S.steps[m.id]||{};if(S.steps[m.id][d]!==r.count){S.steps[m.id][d]=r.count;n++}});
 (data.sleep||[]).forEach(r=>{const d=String(r.date||'').slice(0,10);if(!d||!(r.hours>0))return;S.sleep[m.id]=S.sleep[m.id]||{};const h=+(+r.hours).toFixed(1);if(S.sleep[m.id][d]!==h){S.sleep[m.id][d]=h;n++}});
 const add=(r,o)=>{const key='hc:'+(r.id||(o.t+':'+Object.keys(o).join('')));if(have.has(key))return;have.add(key);V.push(Object.assign({id:'v'+Math.random().toString(36).slice(2,9),t:+r.t||Date.now(),src:'hc',dev:P('Phone (Health Connect)'),hc:key},o));n++};
 (data.heartRate||[]).forEach(r=>{if(r.bpm>20)add(r,{hr:Math.round(r.bpm)})});
 (data.bloodPressure||[]).forEach(r=>{if(r.sys>50&&r.dia>20)add(r,{sys:Math.round(r.sys),dia:Math.round(r.dia)})});
 (data.glucose||[]).forEach(r=>{if(r.mgdl>10)add(r,{glu:Math.round(r.mgdl),gt:r.when||''})});
 (data.spo2||[]).forEach(r=>{if(r.pct>50)add(r,{spo2:Math.round(r.pct)})});
 const ws=(data.weight||[]).filter(r=>r.kg>2).sort((a,b)=>a.t-b.t);ws.forEach(r=>add(r,{w:+(+r.kg).toFixed(1)}));if(ws.length){m.w=+(+ws[ws.length-1].kg).toFixed(1)}
 V.sort((a,b)=>a.t-b.t);if(V.length>2000)S.vitals[m.id]=V.slice(-2000);return n}
SX.act.hcsync=async()=>{const hs=plug('HealthSync');const m=SX.me();if(!hs){SX.modal(`<h2>📱 ${P('Health Connect')}</h2><p>${P('Steps, sleep, heart rate, weight, blood pressure, sugar and SpO₂ from your watch or band arrive automatically with the TheHealthTracker Android app, through Health Connect.')}</p><p class="mute sm">${P('Open this page in the app to sync. Bluetooth devices can still be read directly here.')}</p><div class="lv-row-end"><button class="btn p" data-sx="closeModal">${P('OK')}</button></div>`,{label:'Health Connect'});return}
 SX.modal(`<h2>📱 ${P('Health Connect')}</h2><p class="mute sm" id="hcst">${P('Checking…')}</p><div class="lv10-hcgrid" id="hcgrid"></div><p class="full lv-err" hidden></p><div class="lv-row-end"><button class="btn s" data-sx="closeModal">${P('Close')}</button><button class="btn p" id="hcgo" disabled>${P('Sync now')}</button></div>`,{label:'Health Connect'});
 const st=document.getElementById('hcst'),err=document.querySelector('.sx-modal .lv-err'),go=document.getElementById('hcgo');
 try{const a=await hs.available();if(!a.available){st.textContent=P('Health Connect is not installed on this phone.');err.innerHTML=`${P('Install Health Connect from the Play Store, connect your watch app to it, then come back.')} <a href="https://play.google.com/store/apps/details?id=com.google.android.apps.healthdata" target="_blank" rel="noopener">${P('Open Play Store')}</a>`;err.hidden=false;return}
  const p=await hs.requestPermissions();const got=p.granted||[];st.textContent=got.length?P('Allowed:')+' '+got.map(k=>P(HC_FIELDS[k]||k)).join(', '):P('No permissions were allowed. Tap Sync to ask again.');go.disabled=false;
  go.onclick=async()=>{go.disabled=true;st.textContent=P('Reading the last 30 days…');try{const d=await hs.read({days:30});const n=hcMerge(m,d);S.hc[m.id]={t:Date.now(),n};SX.ledger('reading',true,'Synced from Health Connect',m.id);SX.save();
   document.getElementById('hcgrid').innerHTML=Object.keys(HC_FIELDS).map(k=>`<div><small>${P(HC_FIELDS[k])}</small><b>${(d[k]||[]).length}</b></div>`).join('');st.textContent=n?P('Added')+' '+n+' '+P('new readings for')+' '+E(m.name.split(' ')[0]):P('Nothing new since the last sync.');go.textContent=P('Done');go.onclick=()=>{SX.closeModal();render()}}catch(e){err.textContent=e.message||P('Could not read');err.hidden=false;go.disabled=false}}}
 catch(e){err.textContent=e.message||P('Health Connect is not available');err.hidden=false}};
// on the phone, "Read from a device" means Health Connect (the app's WebView has no Web Bluetooth)
if(SX.native){const ble0=SX.act.bledev;SX.act.bledev=()=>SX.act.hcsync();void ble0}
// steps and sleep from the phone on Today
const stepsCard=m=>{const st=S.steps[m.id]||{},sl=S.sleep[m.id]||{},days=[...Array(7)].map((_,i)=>{const d=new Date();d.setDate(d.getDate()-6+i);return d.toISOString().slice(0,10)});
 const has=days.some(d=>st[d]||sl[d]);if(!has)return SX.native?`<div class="card lv10-hc"><div class="hd"><div><h3>📱 ${P('Phone & watch')}</h3><small class="mute">${P('Steps, sleep and heart rate from Health Connect.')}</small></div><button class="btn p sm" data-sx="hcsync">${P('Connect')}</button></div></div>`:'';
 const mx=Math.max(1,...days.map(d=>st[d]||0)),today=days[6],sl7=days.map(d=>sl[d]).filter(Boolean),avg=sl7.length?(sl7.reduce((a,b)=>a+b,0)/sl7.length).toFixed(1):null;
 return `<div class="card lv10-hc"><div class="hd"><div><h3>📱 ${P('Phone & watch')}</h3><small class="mute">${st[today]?st[today].toLocaleString('en-IN')+' '+P('steps today'):P('No steps yet today')}${avg?' · '+P('sleep')+' '+avg+' h '+P('avg'):''}</small></div>${SX.native?`<button class="btn s sm" data-sx="hcsync">↻</button>`:''}</div>
  <div class="lv10-bars">${days.map(d=>`<div title="${dmy(d)}: ${(st[d]||0).toLocaleString('en-IN')} ${P('steps')}${sl[d]?' · '+sl[d]+' h':''}"><i style="height:${Math.round(100*(st[d]||0)/mx)}%" class="${(st[d]||0)>=8000?'ok':''}"></i><small>${new Date(d).toLocaleDateString('en-IN',{weekday:'narrow'})}</small></div>`).join('')}</div></div>`};
// native push: the phone's token goes to the server as an fcm: endpoint
async function nativePush(){const pn=plug('PushNotifications');if(!pn||!SX.user)return {ok:false};try{let p=await pn.checkPermissions();if(p.receive!=='granted')p=await pn.requestPermissions();if(p.receive!=='granted')return {ok:false,why:P('Notifications not allowed')};
 return await new Promise(res=>{let done=false;pn.addListener('registration',async t=>{if(done)return;done=true;try{await J('/push/subscribe','POST',{subscription:{endpoint:'fcm:'+t.value,keys:{},platform:'android'}});S.rem.push=true;SX.save();res({ok:true})}catch(e){res({ok:false,why:e.message})}});pn.addListener('registrationError',e=>{if(!done){done=true;res({ok:false,why:(e&&e.error)||'registration failed'})}});pn.register();setTimeout(()=>{if(!done){done=true;res({ok:false,why:'timeout'})}},15000)})}catch(e){return {ok:false,why:e.message}}}
if(SX.native){const rp=SX.act.remperm;SX.act.remperm=async()=>{const r=await nativePush();if(r.ok)toast(P('Phone notifications on, even when the app is closed'));else toast(P('Reminders on while the app is open')+(r.why?' · '+r.why:''));if(SX.act.remset)SX.act.remset()};void rp;
 const pn=plug('PushNotifications');if(pn){pn.addListener('pushNotificationActionPerformed',a=>{try{const u=(a.notification&&a.notification.data&&a.notification.data.url)||'';const mm=/#call=([A-Za-z0-9_-]+)/.exec(u);if(mm){SX.act.joincall([mm[1]]);return}const pg=/#page=([a-z]+)/.exec(u);if(pg&&PAGES[pg[1]])go(pg[1]);else go('dash')}catch(e){}});pn.addListener('pushNotificationReceived',n=>{try{toast(n.title||'')}catch(e){}})}
 const app=plug('App');if(app)app.addListener('backButton',()=>{if(document.querySelector('.sx-modal')){SX.closeModal();return}if(window.__callOpen){SX.act.hangup();return}if(page!=='dash')go('dash');else app.minimizeApp&&app.minimizeApp()});
 const sb=plug('StatusBar');if(sb){try{sb.setBackgroundColor({color:'#0b1220'});sb.setStyle({style:'DARK'})}catch(e){}}
 // when signed in, make sure the phone is registered for push (once per install)
 setTimeout(async()=>{if(SX.user&&!S.rem.push)await nativePush()},4000)}

// ---------------------------------------------------------------- B. video consults with a doctor (WebRTC, signalled through the server; media peer to peer)
let CALL=null;const CAP_LANG={en:'en-IN',hi:'hi-IN',te:'te-IN'};
SX.reg('call',{head:()=>[P('Video visit'),P('Your doctor sees and hears you directly; the call never passes through our servers.')],render:()=>{const c=CALL;if(!c)return `<div class="card wide"><p class="mute" style="margin:0">${P('No call in progress.')} <button class="btn s sm" data-sx="tab:appts">${P('Appointments')}</button></p></div>`;
 if(c.ended)return afterCall(c);
 return `<div class="card wide lv10-call ${c.connected?'on':''}"><div class="lv10-stage"><video id="rv" autoplay playsinline></video><video id="lv" autoplay playsinline muted class="pip"></video>
   <div class="lv10-status">${c.connected?`<span class="dot on"></span>${E(c.doctor||P('Doctor'))} · <span id="calltime">00:00</span>`:c.peer?`<span class="sx-spin sm"></span> ${P('Connecting…')}`:`<span class="dot"></span> ${P('Waiting for')} ${E(c.doctor||P('the doctor'))}…`}</div>
   <div class="lv10-caps" id="caps" ${c.captions?'':'hidden'}>${c.lines.slice(-3).map(l=>`<p class="${l.who}"><b>${l.who==='doctor'?'Dr':P('You')}</b> ${E(l.text)}</p>`).join('')}</div></div>
  <div class="lv10-ctl"><button class="${c.muted?'off':''}" data-sx="callmute" aria-label="${E(P('Mute'))}">${c.muted?'🔇':'🎤'}<small>${c.muted?P('Unmute'):P('Mute')}</small></button><button class="${c.camOff?'off':''}" data-sx="callcam">${c.camOff?'🚫':'📷'}<small>${P('Camera')}</small></button><button data-sx="callflip">🔄<small>${P('Flip')}</small></button><button class="${c.captions?'':'off'}" data-sx="callcaps">💬<small>${P('Captions')}</small></button><button class="end" data-sx="hangup">📵<small>${P('End')}</small></button></div>
  <p class="mute sm lv10-note">${P('Captions are made on your phone and shared with the doctor live; at the end you choose whether to keep the transcript for a summary.')}${c.ice&&c.ice.turn?'':' '+P('On some mobile networks the call may not connect without a relay; use Wi-Fi if it does not.')}</p></div>`},
 after(){const c=CALL;if(!c||c.ended)return;window.__callOpen=true;const rv=document.getElementById('rv'),lv=document.getElementById('lv');if(rv&&c.remote)rv.srcObject=c.remote;if(lv&&c.local)lv.srcObject=c.local;tickTimer()}});
function tickTimer(){const c=CALL;if(!c||!c.t0)return;const el=document.getElementById('calltime');if(!el)return;const s=Math.floor((Date.now()-c.t0)/1000);el.textContent=String(Math.floor(s/60)).padStart(2,'0')+':'+String(s%60).padStart(2,'0');setTimeout(tickTimer,1000)}
function afterCall(c){const r=c.result||{};const rx=r.rx;return `<div class="card wide lv10-after"><div class="hd"><div><h3>✓ ${P('Visit ended')}</h3><small class="mute">${E(r.store?r.store.name:'')}${r.doctor?' · Dr '+E(r.doctor):''} · ${P('Duration')} ${c.t0?Math.max(1,Math.round((c.tEnd-c.t0)/60000)):0} ${P('min')}</small></div><button class="btn s sm" data-sx="tab:appts">${P('Appointments')}</button></div>
 ${r.summary?`<div class="lv10-sum">${r.summary.split('\n').map(l=>/^(What we discussed|What the doctor advised|Medicines|Watch for|Next steps)/.test(l.trim())?`<h4>${E(l.trim())}</h4>`:l.trim()?`<p>${E(l.trim())}</p>`:'').join('')}<small class="mute">${P('Written by the health assistant from the captions and the prescription, for discussion with your doctor. Not a diagnosis.')}</small></div>`:c.kept?`<p class="mute sm">${c.summarising?'<span class="sx-spin sm"></span> '+P('Writing the visit summary…'):P('The summary could not be written right now.')+` <button class="btn s sm" data-sx="callsum:${E(c.id)}">${P('Try again')}</button>`}</p>`:`<p class="mute sm">${P('The transcript was not kept, so there is no summary.')}</p>`}
 ${rx&&rx.items?`<div class="lv10-rx"><h4>℞ ${P('Prescription')} · Dr ${E(rx.doctor||'')}</h4><ul>${rx.items.map(i=>`<li><b>${E(i.name)} ${E(i.strength||'')}</b> <span>${E(FREQ[i.frequency]||i.frequency||'')}${i.duration?' · '+E(i.duration):''}${i.instructions?' · '+E(i.instructions):''}</span></li>`).join('')}</ul>${rx.advice?`<p>${E(rx.advice)}</p>`:''}${rx.followUp?`<p><b>${P('Follow-up')}:</b> ${E(rx.followUp)}</p>`:''}<div class="row"><button class="btn p sm" data-sx="rxmeds:${E(c.id)}">${P('Add to my medicines')}</button><button class="btn s sm" data-sx="rxorder:${E(c.id)}">${P('Order these')}</button><button class="btn s sm" data-sx="vopen:erx_${E(c.id)}">${P('Open PDF')}</button></div></div>`:`<p class="mute sm">${P('If the doctor sends a prescription, it appears here and in Lab records → Prescriptions.')}</p>`}</div>`}
const FREQ={od:'once a day',bd:'twice a day',tds:'three times a day',qid:'four times a day',sos:'when needed',hs:'at bedtime',weekly:'once a week'};
const WHEN={od:['Morning'],bd:['Morning','Night'],tds:['Morning','Afternoon','Night'],qid:['Morning','Afternoon','Evening','Night'],hs:['Night'],weekly:['Morning'],sos:[]};
async function startCall(aid){if(CALL&&!CALL.ended&&CALL.id===aid){go('call');return}if(CALL&&!CALL.ended)await SX.act.hangup(true);
 let info;try{info=await J('/consults/'+aid)}catch(e){toast(e.message);return}
 const m=SX.member(info.member)||SX.me();CALL={id:aid,doctor:info.doctor,store:info.store,member:m,lines:[],captions:true,muted:false,camOff:false,facing:'user',pending:[]};go('call');
 try{CALL.local=await navigator.mediaDevices.getUserMedia({video:{facingMode:'user',width:{ideal:640},height:{ideal:480}},audio:{echoCancellation:true,noiseSuppression:true}})}catch(e){try{CALL.local=await navigator.mediaDevices.getUserMedia({audio:true});CALL.camOff=true;toast(P('Camera not available; audio only'))}catch(e2){toast(P('Allow the camera and microphone to join the call'));CALL=null;go('appts');return}}
 const proto=location.protocol==='https:'?'wss':'ws';const ws=new WebSocket(`${proto}://${location.host}/ws/call/${aid}?key=${encodeURIComponent(S.key||'')}`);CALL.ws=ws;
 ws.onmessage=async ev=>{let msg;try{msg=JSON.parse(ev.data)}catch(e){return}const c=CALL;if(!c||c.ws!==ws)return;
  if(msg.type==='hello'){c.ice=msg;c.peer=msg.peerPresent;ensurePC();render();return}
  if(msg.type==='peer'){c.peer=msg.present;if(!msg.present&&c.connected){c.connected=false;toast(P('The doctor left the call'));}render();return}
  if(msg.type==='offer'){ensurePC();try{await c.pc.setRemoteDescription({type:'offer',sdp:msg.sdp});for(const cand of c.pending)await c.pc.addIceCandidate(cand);c.pending=[];const ans=await c.pc.createAnswer();await c.pc.setLocalDescription(ans);ws.send(JSON.stringify({type:'answer',sdp:ans.sdp}))}catch(e){console.warn(e)}return}
  if(msg.type==='ice'&&msg.candidate){try{if(c.pc&&c.pc.remoteDescription)await c.pc.addIceCandidate(msg.candidate);else c.pending.push(msg.candidate)}catch(e){}return}
  if(msg.type==='caption'){c.lines.push({who:'doctor',t:msg.t||Date.now(),text:String(msg.text||'').slice(0,400)});paintCaps();return}
  if(msg.type==='hangup'){toast(P('The doctor ended the visit'));SX.act.hangup();return}};
 ws.onclose=()=>{const c=CALL;if(c&&c.ws===ws&&!c.ended){c.peer=false;c.connected=false;try{render()}catch(e){}}};
 startCaptions();}
function ensurePC(){const c=CALL;if(!c||c.pc)return;const pc=new RTCPeerConnection({iceServers:(c.ice&&c.ice.ice)||[{urls:['stun:stun.l.google.com:19302']}]});c.pc=pc;c.remote=new MediaStream();
 (c.local?c.local.getTracks():[]).forEach(t=>pc.addTrack(t,c.local));
 pc.ontrack=e=>{e.streams[0]?e.streams[0].getTracks().forEach(t=>c.remote.addTrack(t)):c.remote.addTrack(e.track);const rv=document.getElementById('rv');if(rv&&rv.srcObject!==c.remote)rv.srcObject=c.remote};
 pc.onicecandidate=e=>{if(e.candidate&&c.ws&&c.ws.readyState===1)c.ws.send(JSON.stringify({type:'ice',candidate:e.candidate}))};
 pc.onconnectionstatechange=()=>{const st=pc.connectionState;if(st==='connected'){if(!c.connected){c.connected=true;c.t0=c.t0||Date.now();render()}}else if(st==='failed'){c.connected=false;toast(P('Connection lost; trying again…'));try{pc.restartIce()}catch(e){}render()}else if(st==='disconnected'){c.connected=false;render()}}}
function paintCaps(){const c=CALL;const el=document.getElementById('caps');if(!el||!c)return;el.innerHTML=c.lines.slice(-3).map(l=>`<p class="${l.who}"><b>${l.who==='doctor'?'Dr':P('You')}</b> ${E(l.text)}</p>`).join('')}
function startCaptions(){const c=CALL;const SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SR||!c)return;try{const r=new SR();r.lang=CAP_LANG[S.lang]||'en-IN';r.continuous=true;r.interimResults=false;r.onresult=e=>{for(let i=e.resultIndex;i<e.results.length;i++){const res=e.results[i];if(!res.isFinal)continue;const text=res[0].transcript.trim();if(!text)continue;const line={who:'family',t:Date.now(),text};c.lines.push(line);paintCaps();if(c.ws&&c.ws.readyState===1&&c.captions)c.ws.send(JSON.stringify({type:'caption',text,t:line.t}))}};r.onend=()=>{if(CALL===c&&!c.ended&&c.captions){try{r.start()}catch(e){}}};r.onerror=()=>{};c.sr=r;r.start()}catch(e){}}
SX.act.joincall=([aid])=>{try{SX.closeModal()}catch(e){}startCall(aid)};
SX.act.callmute=()=>{const c=CALL;if(!c||!c.local)return;c.muted=!c.muted;c.local.getAudioTracks().forEach(t=>t.enabled=!c.muted);if(c.ws&&c.ws.readyState===1)c.ws.send(JSON.stringify({type:'mute',audio:c.muted}));render()};
SX.act.callcam=()=>{const c=CALL;if(!c||!c.local)return;c.camOff=!c.camOff;c.local.getVideoTracks().forEach(t=>t.enabled=!c.camOff);render()};
SX.act.callflip=async()=>{const c=CALL;if(!c||!c.local||!c.pc)return;c.facing=c.facing==='user'?'environment':'user';try{const s=await navigator.mediaDevices.getUserMedia({video:{facingMode:c.facing},audio:false});const nt=s.getVideoTracks()[0],ot=c.local.getVideoTracks()[0];const sender=c.pc.getSenders().find(x=>x.track&&x.track.kind==='video');if(sender)await sender.replaceTrack(nt);if(ot){c.local.removeTrack(ot);ot.stop()}c.local.addTrack(nt);const lv=document.getElementById('lv');if(lv)lv.srcObject=c.local}catch(e){toast(P('Could not switch camera'))}};
SX.act.callcaps=()=>{const c=CALL;if(!c)return;c.captions=!c.captions;if(c.captions)startCaptions();else if(c.sr){try{c.sr.stop()}catch(e){}}render()};
SX.act.hangup=async(silent)=>{const c=CALL;if(!c||c.ended)return;window.__callOpen=false;try{if(c.ws&&c.ws.readyState===1)c.ws.send(JSON.stringify({type:'hangup'}))}catch(e){}
 try{if(c.sr)c.sr.stop()}catch(e){}try{if(c.pc)c.pc.close()}catch(e){}try{if(c.local)c.local.getTracks().forEach(t=>t.stop())}catch(e){}try{if(c.ws)c.ws.close()}catch(e){}
 c.ended=true;c.tEnd=Date.now();if(silent===true){CALL=null;return}
 const keep=c.lines.length?await new Promise(res=>{SX.modal(`<h2>${P('Keep the transcript?')}</h2><p>${P('The captions from this visit')} (${c.lines.length} ${P('lines')}) ${P('can be saved with the appointment so the health assistant writes a plain-words summary and the doctor’s advice is not lost. They stay in your family’s encrypted record.')}</p><div class="lv-row-end"><button class="btn s" id="tdrop">${P('Discard')}</button><button class="btn p" id="tkeep">${P('Keep & summarise')}</button></div>`,{label:'Transcript'});document.getElementById('tkeep').onclick=()=>{SX.closeModal();res(true)};document.getElementById('tdrop').onclick=()=>{SX.closeModal();res(false)};document.querySelector('.sx-modal')._onclose=()=>res(false)}):false;
 c.kept=keep;c.summarising=keep;render();
 try{const r=await J(`/consults/${c.id}/end`,'POST',{transcript:keep?c.lines:[],keep});c.result=r;c.summarising=false;if(r.summary||r.rx)recordVisit(c,r)}catch(e){c.summarising=false;toast(e.message)}
 render()};
SX.act.callsum=async([aid])=>{const c=CALL;if(!c)return;c.summarising=true;render();try{c.result=await J(`/consults/${aid}/summary`,'POST',{});recordVisit(c,c.result)}catch(e){toast(e.message)}c.summarising=false;render()};
function recordVisit(c,r){const m=c.member||SX.me();const arr=(S.appts[m.id]=S.appts[m.id]||[]);const v=arr.find(x=>x.partner===c.id);if(v){if(r.summary)v.notes=r.summary;v.done=true;if(r.rx)v.rx=r.rx}SX.save()}
SX.act.rxmeds=([aid])=>{const c=CALL&&CALL.id===aid?CALL:null;const rx=c&&c.result&&c.result.rx;if(!rx)return;const m=c.member||SX.me();const meds=(S.meds[m.id]=S.meds[m.id]||[]);let n=0;rx.items.forEach(i=>{const name=(i.name+' '+(i.strength||'')).trim();if(meds.some(x=>x.n.toLowerCase()===name.toLowerCase()))return;meds.push({id:'md'+Math.random().toString(36).slice(2,9),n:name,s:i.strength||'',when:WHEN[i.frequency]||['Morning'],dur:i.duration||'',note:i.instructions||'',by:'Dr '+(rx.doctor||''),from:'erx_'+aid,t:Date.now()});n++});SX.ledger('medicine',true,`Added ${n} medicines from Dr ${rx.doctor||''}'s prescription`,m.id);SX.save();toast(n?P('Added')+' '+n+' '+P('medicines'):P('Already in the list'));go('rx')};
SX.act.rxorder=([aid])=>{const c=CALL&&CALL.id===aid?CALL:null;const rx=c&&c.result&&c.result.rx;if(!rx)return;S.rxWanted={aid,items:rx.items.map(i=>i.name),file:'erx_'+aid,t:Date.now()};SX.save();go('finder');toast(P('Search each medicine and add it; the e-prescription is attached automatically'))};
SX.act.vopen=async([fid])=>{try{const b=await SX.files.get(fid);if(!b){toast(P('Not on this device yet'));return}const u=URL.createObjectURL(b);window.open(u,'_blank','noopener');setTimeout(()=>URL.revokeObjectURL(u),60000)}catch(e){toast(P('Could not open'))}};
// the e-prescription reaches the vault like a lab report, so the pharmacy Rx gate accepts it
