// notices: new kinds get icons, destinations and buttons
const notes10=SX.notes;SX.notes=()=>{const out=notes10();const IC={consult:'📹',prescription:'℞',weekly:'📊',nudge_test:'🧪',nudge_vax:'💉',nudge_policy:'🛡️',nudge_preg:'🤱',nudge_care:'🩺',nudge_drift:'📈',nudge_handover:'🎓'};const GO={consult:'appts',prescription:'vault',weekly:'dash',nudge_test:'nearlabs',nudge_vax:'vax',nudge_policy:'wallet',nudge_preg:'preg',nudge_care:'careplan',nudge_drift:'assist',nudge_handover:'family'};
 out.forEach(o=>{if(!o.srv)return;const n=S.inbox.find(x=>x.id===o.srv);if(!n||!IC[n.kind])return;o.ic=IC[n.kind];o.go=GO[n.kind]||o.go;if(n.kind==='consult'&&n.ref&&n.ref.join)o.acts=[['joincall:'+n.ref.appointment,P('Join call')]];if(n.kind==='weekly')o.acts=[['weekly',P('Read')]]});return out};
// a fresh "doctor is ready" notice opens a join prompt wherever the person is
let seenJoin=new Set();setInterval(()=>{const n=(S.inbox||[]).find(x=>x.kind==='consult'&&!x.read&&x.ref&&x.ref.join&&!seenJoin.has(x.id)&&Date.now()/1000-x.t<1800);if(!n)return;seenJoin.add(n.id);if(CALL&&!CALL.ended)return;SX.modal(`<h2>📹 ${E(n.title)}</h2><p>${E(n.body)}</p><div class="lv-row-end"><button class="btn s" data-sx="closeModal">${P('Not now')}</button><button class="btn p" data-sx="joincall:${E(n.ref.appointment)}">${P('Join the call')}</button></div>`,{label:'Video visit'})},3000);
// appointments: a Join button on live video visits, a summary when done
SX.extend('appts',{mounted(){(S.partnerAppts||[]).forEach(a=>{if(a.kind!=='video')return;const btn=document.querySelector(`[data-sx="apcancel:${a.id}"],[data-sx="msgto:${a.store?a.store.id:''}"]`);if(!btn)return;const row=btn.closest('.lv7-ap');if(!row||row.querySelector('.lv10-join'))return;
 if(a.live)row.insertAdjacentHTML('beforeend',`<button class="btn p sm lv10-join" data-sx="joincall:${E(a.id)}">📹 ${P('Join')}</button>`);else if(a.hasSummary||a.hasRx)row.insertAdjacentHTML('beforeend',`<button class="btn s sm lv10-join" data-sx="consum:${E(a.id)}">📄 ${P('Summary')}</button>`);else if(['confirmed','rescheduled'].includes(a.status))row.insertAdjacentHTML('beforeend',`<span class="lv10-vid" title="${E(P('Video visit: you will get a notification when the doctor starts'))}">📹</span>`)})}});
SX.act.consum=async([aid])=>{try{const r=await J('/consults/'+aid);CALL={id:aid,ended:true,result:r,member:SX.member(r.member)||SX.me(),kept:true,t0:r.callStarted?r.callStarted*1000:0,tEnd:r.callEnded?r.callEnded*1000:0,doctor:r.doctor,store:r.store};go('call')}catch(e){toast(e.message)}};
// deep link from a push: /app#call=<id>
if(/#call=/.test(location.hash)){const id=/#call=([A-Za-z0-9_-]+)/.exec(location.hash)[1];history.replaceState(null,'',location.pathname);setTimeout(()=>{if(S.key)startCall(id)},1500)}
if(/#page=/.test(location.hash)){const pg=/#page=([a-z]+)/.exec(location.hash)[1];history.replaceState(null,'',location.pathname);setTimeout(()=>{try{if(PAGES[pg])go(pg)}catch(e){}},800)}

// ---------------------------------------------------------------- C. the assistant acts: command buttons under answers
