SX.act.agcmd=([t,i])=>{const m=SX.me(),a=(S.ask[m.id]||[]).find(x=>String(x.t)===String(t));const c=a&&a.cmd&&a.cmd[+i];if(!c)return;const g=c.args||{};
 if(c.type==='open'){go(g.page);return}
 if(c.type==='book_lab'){S.labWanted={tests:g.tests,t:Date.now()};SX.save();go('nearlabs');toast(P('Choose a lab for')+' '+g.tests.join(', '));return}
 if(c.type==='request_visit'){go('nearlabs');setTimeout(()=>{const b=document.querySelector('[data-sx^="bookat:"]');if(b)b.click();else toast(P('Pick a partner hospital under Nearby'))},400);return}
 if(c.type==='add_reminder'){const d=new Date();d.setDate(d.getDate()+(g.days||7));const day=d.toISOString().slice(0,10);(S.appts[m.id]=S.appts[m.id]||[]).push({id:'ap'+Math.random().toString(36).slice(2,9),dn:g.text,dh:P('Reminder'),date:day,time:'09:00',why:g.text,type:'Reminder'});SX.ledger('appointment',true,'Reminder: '+g.text,m.id);SX.save();toast(P('Reminder set for')+' '+dmy(day));return}
 if(c.type==='add_reading'){const b=document.querySelector('[data-sx="vital"],[data-sx^="addvital"],[data-sx="addv"]');if(b)b.click();else go('heart')}};

// ---------------------------------------------------------------- D. the weekly family report (Home → Today)
S.weekly=S.weekly||{};
const trendArrow=s=>s.change==null?'':s.change>0?'↑ ':s.change<0?'↓ ':'→ ';
function weeklyHTML(){const w=S.weekly.data;if(!w)return `<div class="card lv10-week"><div class="hd"><div><h3>📊 ${P('Weekly report')}</h3><small class="mute">${P('Four weeks of readings and results against the four before: trends, control, adherence.')}</small></div><button class="btn p sm" data-sx="weekly">${S.weekly.busy?'<span class="sx-spin sm"></span>':P('Prepare')}</button></div></div>`;
 return `<div class="card lv10-week"><div class="hd"><div><h3>📊 ${P('Weekly report')}</h3><small class="mute">${dmy(w.from)} – ${dmy(w.to)}</small></div><button class="btn s sm" data-sx="weekly">↻</button></div>${w.narrative?`<p class="lv10-narr">${E(w.narrative)}</p>`:''}
  ${w.people.filter(p=>p.readings||p.labs.length||p.pregnancy).map(p=>`<div class="lv10-person"><b>${E(p.name)}</b>${p.anomalies.length?`<span class="lv10-anom">⚠ ${p.anomalies.length} ${P('readings needed urgent attention')}</span>`:''}
   <div class="lv10-kpis">${p.bpControl!=null?`<div><small>${P('BP in control')}</small><b class="${p.bpControl>=70?'ok':'warn'}">${p.bpControl}%</b></div>`:''}${p.adherence!=null?`<div><small>${P('Doses taken')}</small><b class="${p.adherence>=80?'ok':'warn'}">${p.adherence}%</b></div>`:''}<div><small>${P('Readings')}</small><b>${p.readings}</b></div></div>
   ${p.series.length?`<div class="lv10-series">${p.series.map(s=>`<div><span>${E(P(s.label))}</span><b>${trendArrow(s)}${s.mean} <small>${E(s.unit)}</small></b><small>${s.previous!=null?P('was')+' '+s.previous:''}${s.perWeek?' · '+(s.perWeek>0?'+':'')+s.perWeek+'/'+P('wk'):''} · ${s.inRange}% ${P('in range')}</small></div>`).join('')}</div>`:''}
   ${p.labs.length?`<div class="lv10-labs">${p.labs.map(l=>`<span class="${l.flag}">${E(l.name)} ${l.value}${l.previous!=null?` <i>(${P('was')} ${l.previous})</i>`:''}</span>`).join('')}</div>`:''}
   ${p.pregnancy?`<p class="mute sm">🤱 ${P('Week')} ${p.pregnancy.week}${p.pregnancy.gain!=null?` · ${P('weight gain')} ${p.pregnancy.gain} kg (${P('expected')} ${p.pregnancy.expected[0]}–${p.pregnancy.expected[1]} kg)`:''}</p>`:''}</div>`).join('')||`<p class="mute sm">${P('No readings in the last four weeks. Add a few and the report fills in.')}</p>`}
  <small class="mute">${P('Computed from your family’s own record; the opening lines are written by the health assistant. For discussion with your doctor.')}</small></div>`}
SX.act.weekly=async()=>{if(S.weekly.busy)return;S.weekly.busy=true;render();try{const r=await J('/report/weekly?lang='+(S.lang||'en'));S.weekly={data:r,t:Date.now()};SX.save()}catch(e){toast(e.message)}S.weekly.busy=false;render()};
SX.extend('dash',{before(){return S.weekly.data?weeklyHTML():''},after(){const m=SX.me();const stale=!S.weekly.data||Date.now()-(S.weekly.t||0)>6*864e5;if(stale&&new Date().getDay()===1&&!S.weekly.busy&&S.key&&!S.weekly.auto){S.weekly.auto=true;setTimeout(SX.act.weekly,1500)}return stepsCard(m)+(S.weekly.data?'':weeklyHTML())}});
// daily adherence snapshot so the report can count doses (today's ticks only live in `taken`)
setInterval(()=>{try{S.members.forEach(m=>{const t=S.taken[m.id];if(!t||t.d!==SX.today())return;const plan=SX.dosePlan?SX.dosePlan(m):[];if(!plan.length)return;S.adh[m.id]=S.adh[m.id]||{};const done=Object.keys(t.s||{}).length,cur=S.adh[m.id][t.d];if(!cur||cur.done!==done||cur.total!==plan.length){S.adh[m.id][t.d]={done,total:plan.length};Object.keys(S.adh[m.id]).sort().slice(0,-120).forEach(k=>delete S.adh[m.id][k]);SX.save()}})}catch(e){}},30000);

// ---------------------------------------------------------------- E. lock-screen Medical ID with QR
S.medid=S.medid||{};
function midPayload(m){const d=SX.midOf(m.id),meds=(S.meds[m.id]||[]).map(x=>x.n).slice(0,12),cs=(SX.contactsOf?SX.contactsOf(m.id):(S.contacts[m.id]||[])).filter(c=>c.ph).slice(0,4).map(c=>({name:c.n,rel:c.rel,phone:c.ph}));
 const p={name:m.name,age:m.age,sex:m.sex==='female'?'F':m.sex==='male'?'M':'',blood:d.blood||'',allergies:d.allergies||[],conditions:d.conditions||[],medicines:meds,contacts:cs,donor:d.donor==='yes'?P('Organ donor'):'',doctor:d.doctor||'',notes:(d.notes||'').slice(0,200),pregnant:!!(SX.pregOn&&SX.pregOn(m)),lang:S.lang||'en'};const opt=S.medid[m.id]&&S.medid[m.id].opt||{};if(opt.noMeds)p.medicines=[];if(opt.noCond)p.conditions=[];return p}
SX.extend('mid',{after(){const m=SX.me(),r=S.medid[m.id];return `<div class="card lv10-mid"><div class="hd"><div><h3>🔗 ${P('Lock-screen Medical ID')}</h3><small class="mute">${P('A link and QR code a responder can open without unlocking your phone: blood group, allergies, conditions, medicines, who to call.')}</small></div>${r&&r.enabled?`<button class="btn s sm" data-sx="midoff">${P('Switch off')}</button>`:`<button class="btn p sm" data-sx="midon">${P('Switch on')}</button>`}</div>
 ${r&&r.enabled?`<div class="lv10-midg"><div class="lv10-qr"><img src="/api/v1/medical-id/${E(m.id)}/qr.svg?v=${r.updated||0}" alt="QR" data-fetch="${E(m.id)}"></div><div><p class="sm" style="margin:0 0 6px"><a href="${E(r.url)}" target="_blank" rel="noopener">${E(r.url.replace(/^https?:\/\//,''))}</a></p><p class="mute sm" style="margin:0 0 8px">${P('Viewed')} ${r.views||0} ${P('times')}${r.lastView?' · '+P('last')+' '+SX.fmt(r.lastView*1000):''}. ${P('Updated when you change these details.')}</p>
   <div class="row" style="flex-wrap:wrap"><button class="btn s sm" data-sx="midcopy">${P('Copy link')}</button><button class="btn s sm" data-sx="midprint">${P('Print / wallet card')}</button><button class="btn s sm" data-sx="midrotate">${P('New link')}</button></div>
   <label class="lv-opt" style="display:flex;gap:8px;align-items:center;margin-top:8px"><input type="checkbox" data-sxc="midopt:noMeds" ${r.opt&&r.opt.noMeds?'checked':''}><span>${P('Hide medicines')}</span></label><label class="lv-opt" style="display:flex;gap:8px;align-items:center"><input type="checkbox" data-sxc="midopt:noCond" ${r.opt&&r.opt.noCond?'checked':''}><span>${P('Hide conditions')}</span></label>
   <p class="mute sm" style="margin:8px 0 0">${P('Android: set the QR as your lock-screen wallpaper or add the link under Settings → Safety & emergency → Medical info. iPhone: Health → Medical ID.')}</p></div></div>`:`<p class="mute sm" style="margin:0">${P('Off. Nothing is published until you switch it on; you can rotate or switch off the link any time.')}</p>`}</div>`},
 mounted(){const img=document.querySelector('.lv10-qr img[data-fetch]');if(!img)return;fetch(img.getAttribute('src'),{headers:{'x-dokko-key':S.key||''},credentials:'same-origin'}).then(r=>r.ok?r.text():Promise.reject()).then(svg=>{img.replaceWith(Object.assign(document.createElement('div'),{innerHTML:svg,className:'lv10-svg'}))}).catch(()=>{img.alt=P('QR unavailable')})}});
async function midPublish(m,rotate){try{const r=await J(`/medical-id/${m.id}`,'PUT',{payload:midPayload(m),rotate:!!rotate});S.medid[m.id]={...r,opt:(S.medid[m.id]||{}).opt||{}};SX.ledger('medid',true,rotate?'Medical ID link rotated':'Medical ID published',m.id);SX.save();render()}catch(e){toast(e.message)}}
SX.act.midon=()=>midPublish(SX.me());SX.act.midrotate=()=>midPublish(SX.me(),true);
SX.act.midoff=async()=>{const m=SX.me();try{const r=await J(`/medical-id/${m.id}/off`,'POST',{});S.medid[m.id]={...S.medid[m.id],...r};SX.ledger('medid',false,'Medical ID switched off',m.id);SX.save();render()}catch(e){toast(e.message)}};
