SX.act.polread=([id])=>{const c=(S.cards||[]).find(x=>x.id===id);if(!c)return;const inp=document.createElement('input');inp.type='file';inp.accept='application/pdf,image/*,.txt';inp.onchange=async()=>{const f=inp.files[0];if(!f)return;if(!S.consent.ai_docs&&!S.consent.ai_assist){if(!confirm(P('The document is sent to the TheHealthTracker server to be read, then discarded. Continue?')))return}
 toast(P('Reading the policy…'));const fd=new FormData();fd.append('kind','policy');fd.append('consent','1');fd.append('context','{}');fd.append('file',f,f.name);try{const r=await fetch('/api/v1/ai/analyze',{method:'POST',body:fd,headers:{'x-tht':'1','x-dokko-key':S.key||''},credentials:'same-origin'});const j=await r.json();if(!r.ok)throw new Error(typeof j.detail==='string'?j.detail:'Could not read');if(!j.readable){toast((j.warnings&&j.warnings[0])||P('The document could not be read'));return}
  c.terms={...j,t:Date.now()};delete c.terms.text;delete c.terms.usage;delete c.terms.engine;if(j.valid_to&&!c.f.valid_to)c.f.valid_to=j.valid_to;if(j.sum_insured&&!c.f.sum_insured)c.f.sum_insured=String(j.sum_insured);if(j.tpa&&!c.f.tpa)c.f.tpa=j.tpa;if(j.policy_number&&!c.f.policy_number)c.f.policy_number=j.policy_number;
  try{await SX.files.put('policy:'+c.id,f);c.policyFile={name:f.name,size:f.size,mime:f.type}}catch(e){}SX.ledger('card',true,'Policy document read',c.member);SX.save();render();toast(P('Policy read: check the terms against the original'))}catch(e){toast(e.message)}};inp.click()};
